import heapq


def dependency_solver(name_order, preference):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        options = {}
        for name in names:
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in blocked.get(name, [])
                        and (name not in pins or row["version"] == pins[name])]
            options[name] = [None] + versions

        order = names if name_order == "ascending" else list(reversed(names))
        best = None
        best_vector = None
        for values in product(*(options[name] for name in names)):
            chosen = {name: version for name, version in zip(names, values)
                      if version is not None}
            if any(name not in chosen or
                   not bounds[0] <= chosen[name] <= bounds[1]
                   for name, bounds in data["roots"].items()):
                continue

            edges = {name: [] for name in chosen}
            valid = True
            for name, version in chosen.items():
                row = next(row for row in packages[name]
                           if row["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    target_version = chosen.get(target)
                    if (target_version is None or
                            not dep["min"] <= target_version <= dep["max"]):
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(data["roots"])
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges[name])
            if reachable != set(chosen):
                continue

            finished, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                for target in edges[name]:
                    if not visit(target):
                        return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in chosen):
                continue
            vector = tuple(chosen.get(name, -1) for name in order)
            if (best is None or
                    (vector > best_vector if preference == "maximum"
                     else vector < best_vector)):
                best, best_vector = chosen, vector

        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def component_06(data):
    def rounded(numerator):
        denominator = 10000
        if data["rounding"] == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def component_07(data):
    blocked = set(data.get("blocked", []))
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_ids = None
    best_value = None

    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        if any(sum(job["start"] <= time < job["end"] for job in subset) > 2
               for time in {job["start"] for job in subset}):
            continue

        value = sum(job["value"] for job in subset)
        if (best_ids is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_ids, best_value = ids, value

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def component_08(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full_mask = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full_mask:
            return {"arrival": time}

        for edge in graph[node]:
            departure = max(time, edge["open"])
            if departure >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                discounted = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((discounted, coupons - 1))
            for duration, remaining in options:
                arrival = departure + duration
                if arrival > data["deadline"]:
                    continue
                target = edge["v"]
                next_mask = mask | bits.get(target, 0)
                next_state = (target, next_mask, remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, target, next_mask, remaining))

    return {"arrival": None}


